ValidationRule.errorConditionFormula:
AND(

   NOT( $User.Id = '0051a000002RkQg'),
   /* Doesn't apply to user, Pro Developer */
   NOT( $User.Id = '0051a000002i3pE'),
   /* Doesn't apply to user, Salesforce Data Cycle */
   NOT( $User.Id = '0054z00000AiD1y'),
   /* Doesn't apply to user, salesforce_pro2 production*/

   OR(
      ISPICKVAL(Type, 'Core'),
      ISPICKVAL(Type, 'Accelerated-AGP')
   ),
   ISBLANK(Support_Rep__c)
)
